(()=>{"use strict";new Swiper(".swiper",{slidesPerView:1,loop:!0,autoHeight:!0,speed:1e3,allowTouchMove:!1,autoplay:{delay:2500,disableOnInteraction:!1}});const e=document.querySelector(".header");window.addEventListener("scroll",()=>{window.scrollY>=window.innerHeight?e.classList.add("_scrolled"):e.classList.remove("_scrolled")})})();